// Parse report command
const input = $input.item.json;
const command = input.command;
const args = input.args || '';
const chatId = input.chatId;

const today = new Date();
const formatDate = (d) => d.toISOString().split('T')[0];

let result = {
  command,
  reportType: null,
  startDate: null,
  endDate: null,
  exportFormat: 'text',
  chatId,
  userId: input.userId,
  username: input.username
};

switch (command) {
  case 'report':
    if (args === 'today' || !args) {
      result.reportType = 'candidates';
      result.startDate = formatDate(today);
      result.endDate = formatDate(today);
      result.periodLabel = 'сегодня';
    } else if (args === 'week') {
      const weekAgo = new Date(today);
      weekAgo.setDate(weekAgo.getDate() - 7);
      result.reportType = 'candidates';
      result.startDate = formatDate(weekAgo);
      result.endDate = formatDate(today);
      result.periodLabel = 'за неделю';
    } else if (args === 'month') {
      const monthAgo = new Date(today);
      monthAgo.setMonth(monthAgo.getMonth() - 1);
      result.reportType = 'candidates';
      result.startDate = formatDate(monthAgo);
      result.endDate = formatDate(today);
      result.periodLabel = 'за месяц';
    } else {
      // Parse date range dd.mm-dd.mm
      const dateRangeMatch = args.match(/(\d{1,2})\.(\d{1,2})-(\d{1,2})\.(\d{1,2})/);
      if (dateRangeMatch) {
        const year = today.getFullYear();
        result.reportType = 'candidates';
        result.startDate = `${year}-${dateRangeMatch[2].padStart(2,'0')}-${dateRangeMatch[1].padStart(2,'0')}`;
        result.endDate = `${year}-${dateRangeMatch[4].padStart(2,'0')}-${dateRangeMatch[3].padStart(2,'0')}`;
        result.periodLabel = `${dateRangeMatch[1]}.${dateRangeMatch[2]} - ${dateRangeMatch[3]}.${dateRangeMatch[4]}`;
      } else {
        result.error = 'Неверный формат даты. Используйте: /report week или /report 01.01-31.01';
      }
    }
    break;

  case 'stats':
    result.reportType = args === 'recruiters' ? 'recruiter_stats' : 'funnel_stats';
    result.periodLabel = '30 дней';
    break;

  case 'export':
    result.exportFormat = 'excel';
    const exportParts = args.split(' ');
    result.reportType = exportParts[0] || 'candidates';
    if (exportParts[1] === 'week') {
      const weekAgo = new Date();
      weekAgo.setDate(weekAgo.getDate() - 7);
      result.startDate = formatDate(weekAgo);
      result.endDate = formatDate(new Date());
      result.periodLabel = 'за неделю';
    } else {
      const monthAgo = new Date();
      monthAgo.setMonth(monthAgo.getMonth() - 1);
      result.startDate = formatDate(monthAgo);
      result.endDate = formatDate(new Date());
      result.periodLabel = 'за месяц';
    }
    break;

  default:
    result.error = 'Неизвестная команда';
}

return { json: result };

// Build candidates report
const commandData = $('Parse Command').item.json;
const candidates = $input.all().map(i => i.json);

let report = `📊 *Отчёт по кандидатам*\n`;
report += `📅 Период: ${commandData.periodLabel}\n\n`;

if (candidates.length === 0) {
  report += `_Кандидатов за указанный период не найдено._`;
} else {
  // Группировка по статусам
  const byStatus = {};
  candidates.forEach(c => {
    if (!byStatus[c.status]) byStatus[c.status] = [];
    byStatus[c.status].push(c);
  });

  report += `👥 Всего: ${candidates.length}\n\n`;

  const statusEmoji = {
    'направлен': '📋',
    'собеседование': '🗣',
    'оформление': '📝',
    'работает': '✅',
    'отказ': '❌',
    'архив': '📦'
  };

  for (const [status, list] of Object.entries(byStatus)) {
    report += `${statusEmoji[status] || '•'} ${status}: ${list.length}\n`;
  }

  report += `\n*Последние 10 добавленных:*\n`;

  candidates.slice(0, 10).forEach((c, i) => {
    report += `\n${i + 1}. *${c.full_name}*\n`;
    report += `   📞 ${c.phone || '-'}\n`;
    report += `   💼 ${c.position || '-'} | 📍 ${c.object_location || '-'}\n`;
    report += `   📊 ${c.status}\n`;
  });

  if (candidates.length > 10) {
    report += `\n_...и ещё ${candidates.length - 10} кандидат(ов)_`;
  }
}

const keyboard = {
  inline_keyboard: [
    [
      { text: '📥 Экспорт в Excel', callback_data: `export_candidates_${commandData.startDate}_${commandData.endDate}` }
    ],
    [
      { text: '📊 Статистика воронки', callback_data: 'report_funnel' },
      { text: '👥 По рекрутерам', callback_data: 'report_recruiters' }
    ]
  ]
};

return {
  json: {
    report,
    keyboard,
    chatId: commandData.chatId
  }
};

// Build funnel stats report
const commandData = $('Parse Command').item.json;
const stats = $input.all().map(i => i.json);

let report = `📊 *Воронка найма*\n`;
report += `📅 Последние 30 дней\n\n`;

const statusEmoji = {
  'направлен': '📋',
  'собеседование': '🗣',
  'оформление': '📝',
  'работает': '✅',
  'отказ': '❌',
  'архив': '📦'
};

const total = stats.reduce((sum, s) => sum + parseInt(s.count || 0), 0);

stats.forEach(s => {
  const emoji = statusEmoji[s.status] || '•';
  const percentage = s.percentage || 0;
  const bar = '█'.repeat(Math.round(percentage / 5));
  report += `${emoji} *${s.status}*: ${s.count} (${percentage}%)\n`;
  report += `   ${bar}\n\n`;
});

report += `\n📈 *Конверсия:*\n`;
const hired = stats.find(s => s.status === 'работает')?.count || 0;
const conversionRate = total > 0 ? Math.round((hired / total) * 100) : 0;
report += `Направлен → Работает: ${conversionRate}%`;

return {
  json: {
    report,
    chatId: commandData.chatId
  }
};

// Build recruiter stats report
const commandData = $('Parse Command').item.json;
const stats = $input.all().map(i => i.json);

let report = `👥 *Статистика по рекрутерам*\n`;
report += `📅 Последние 30 дней\n\n`;

if (stats.length === 0) {
  report += `_Данных нет._`;
} else {
  stats.forEach((r, i) => {
    const medal = i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : `${i + 1}.`;
    report += `${medal} @${r.telegram_username || 'Unknown'}\n`;
    report += `   📋 Добавлено: ${r.total_candidates}\n`;
    report += `   ✅ Трудоустроено: ${r.hired_count}\n`;
    report += `   📈 Конверсия: ${r.conversion_rate || 0}%\n\n`;
  });
}

return {
  json: {
    report,
    chatId: commandData.chatId
  }
};
